76	// hooksFiringRemoteSrvStore wraps a RemoteSrvStore and fires CommitHooks
77	// registered on the associated DoltDB after a successful Commit. This is used
78	// when sql-server exposes a remotesapi endpoint so that pushes from remote
79	// clients trigger the same hooks (replication, stats, etc.) as writes through
80	// the SQL engine.
81	type hooksFiringRemoteSrvStore struct {
82		remotesrv.RemoteSrvStore
83		ddb *doltdb.DoltDB
84	}
85	
86	// Commit implements remotesrv.RemoteSrvStore. After a successful commit it
87	// fires the DoltDB's registered CommitHooks for every ref-typed dataset whose
88	// head address changed between |last| and |current|.
89	func (s hooksFiringRemoteSrvStore) Commit(ctx context.Context, current, last hash.Hash) (bool, error) {
90		// Snapshot old dataset head addresses before the commit.
91		oldDatasets, _ := s.ddb.DatasetsByRootHash(ctx, last)
92	
93		ok, err := s.RemoteSrvStore.Commit(ctx, current, last)
94		if !ok || err != nil {
95			return ok, err
96		}
97	
98		// Snapshot new dataset head addresses after the successful commit.
99		newDatasets, err := s.ddb.DatasetsByRootHash(ctx, current)
100		if err != nil {
101			// Don't fail the commit; hooks are best-effort.
102			return true, nil
103		}
104	
105		// Build lookup maps for both old and new dataset head addresses.
106		oldAddrs := make(map[string]hash.Hash)
107		if oldDatasets != nil {
108			_ = oldDatasets.IterAll(ctx, func(id string, addr hash.Hash) error {
109				oldAddrs[id] = addr
110				return nil
111			})
112		}
113		newAddrs := make(map[string]hash.Hash)
114		_ = newDatasets.IterAll(ctx, func(id string, addr hash.Hash) error {
115			newAddrs[id] = addr
116			return nil
117		})
118	
119		// Fire hooks for each ref-typed dataset that was added or changed.
120		for id, newAddr := range newAddrs {
121			if !ref.IsRef(id) {
122				continue
123			}
124			if oldAddr, existed := oldAddrs[id]; !existed || oldAddr != newAddr {
125				_ = s.ddb.ExecuteCommitHooks(ctx, id)
126			}
127		}
128	
129		// Fire hooks for each ref-typed dataset that was deleted.
130		for id := range oldAddrs {
131			if !ref.IsRef(id) {
132				continue
133			}
134			if _, exists := newAddrs[id]; !exists {
135				_ = s.ddb.ExecuteCommitHooks(ctx, id)
136			}
137		}
138	
139		return true, nil
140	}
